"""Content search rendering for the lla CLI."""
import csv
import fnmatch
import io
import os
import re
import json


GRAY = "\x1b[38;2;192;197;206m"
RESET = "\x1b[0m"


def find_matches(root, pattern, context=2, case_sensitive=False, show_hidden=True,
                 file_filter=None, stats=None):
    regex = pattern.startswith("regex:")
    body = pattern[6:] if regex else re.escape(pattern)
    try:
        rx = re.compile(body, 0 if case_sensitive else re.IGNORECASE)
    except re.error:
        return []
    found = []
    def walk(folder):
        try:
            entries = sorted(os.scandir(folder), key=lambda e: e.name.casefold())
        except OSError:
            return
        for e in entries:
            if e.name.startswith(".") and not show_hidden:
                continue
            try:
                if e.is_dir(follow_symlinks=False):
                    walk(e.path)
                elif e.is_file(follow_symlinks=True):
                    if file_filter and not fnmatch.fnmatch(e.name, "*" + file_filter.lstrip(".")) and not fnmatch.fnmatch(e.name, "*" + file_filter):
                        continue
                    try:
                        raw=open(e.path,"rb").read()
                        if stats is not None:
                            stats["searches"]=stats.get("searches",0)+1
                            stats["bytes_searched"]=stats.get("bytes_searched",0)+len(raw)
                        if b"\0" in raw:
                            continue
                        data=raw.decode("utf-8",errors="ignore")
                    except OSError:
                        continue
                    lines = data.splitlines()
                    hits = []
                    for i, line in enumerate(lines):
                        matches = list(rx.finditer(line))
                        if matches:
                            hits.append((i, line, matches))
                    if hits:
                        found.append((e.path, lines, hits))
            except OSError:
                pass
    if os.path.isfile(root):
        try:
            raw=open(root,"rb").read()
            if stats is not None:
                stats["searches"]=stats.get("searches",0)+1
                stats["bytes_searched"]=stats.get("bytes_searched",0)+len(raw)
            lines=raw.decode("utf-8",errors="ignore").splitlines()
            hits=[(i,line,list(rx.finditer(line))) for i,line in enumerate(lines) if rx.search(line)]
            if hits: found.append((root,lines,hits))
        except OSError: pass
    else:
        walk(root)
    return found


def render_search(root, pattern, context=2, case_sensitive=False, show_hidden=True,
                  file_filter=None):
    """Render contextual, line-numbered match output."""
    files=find_matches(root,pattern,context,case_sensitive,show_hidden,file_filter)
    out=[]
    for path, lines, hits in files:
        out += ["", f"File: {os.path.basename(path)} [{os.path.abspath(path)}]"]
        for hitidx,(line_no,line,matches) in enumerate(hits):
            start=max(0,line_no-max(0,context)); end=min(len(lines),line_no+max(0,context)+1)
            if hitidx and start <= hits[hitidx-1][0]+context:
                start=max(start,hits[hitidx-1][0]+context+1)
            for i in range(start,end):
                colored=GRAY+lines[i]+RESET
                out.append(f"{i:4} │ {colored}")
                if i==line_no:
                    marks=[" "]*len(line)
                    for m in matches:
                        for j in range(m.start(),max(m.start()+1,m.end())):
                            if j<len(marks): marks[j]="^"
                    out.append(f"{i:4} │ {''.join(marks)}")
            if hitidx < len(hits)-1: out.append("")
        out.append("")
    return "\n".join(out)


def _display_path(path, root_arg=None):
    if root_arg is None or os.path.isabs(root_arg):
        return os.path.abspath(path)
    if os.path.isfile(root_arg):
        return root_arg
    rel=os.path.relpath(path,os.path.abspath(root_arg))
    return os.path.join(root_arg,rel)


def search_csv(files, root_arg=None):
    output=["file,line,column,kind,text"]
    for path,lines,hits in files:
        for n,line,matches in hits:
            for m in matches:
                text='"'+line.replace('"','""')+'"'
                output.append(f"{_display_path(path,root_arg)} ,{n+1} ,{m.start()+1} ,match ,{text}")
    return "\n".join(output)+"\n"


def search_jsonl(files, context=0, root_arg=None, scan_stats=None):
    """Emit ripgrep-compatible JSONL begin/match/context/end records."""
    output=[]
    total_matches=total_lines=total_bytes=total_searches=0
    for path,lines,hits in files:
        path=_display_path(path,root_arg)
        try:
            with open(path,"rb") as source:
                has_final_newline=source.read().endswith(b"\n")
        except OSError:
            has_final_newline=True
        output.append({"type":"begin","data":{"path":{"text":path}}})
        hit_by_line={n:(line,ms) for n,line,ms in hits}
        relevant=set()
        for n,_,_ in hits:
            relevant.update(range(max(0,n-context),min(len(lines),n+context+1)))
        offsets=[]; off=0
        for i,line in enumerate(lines):
            offsets.append(off)
            ending="\n" if i < len(lines)-1 or has_final_newline else ""
            off+=len((line+ending).encode("utf-8"))
        total_bytes+=off; total_searches+=1
        for n in sorted(relevant):
            line=lines[n]; encoded=line.encode("utf-8")
            text=line+("\n" if n < len(lines)-1 or has_final_newline else "")
            if n in hit_by_line:
                _,ms=hit_by_line[n]
                subs=[]
                for m in ms:
                    start=len(line[:m.start()].encode("utf-8")); end=len(line[:m.end()].encode("utf-8"))
                    subs.append({"match":{"text":m.group(0)},"start":start,"end":end})
                total_matches+=len(ms); total_lines+=1
                item={"type":"match","data":{"path":{"text":path},"lines":{"text":text},"line_number":n+1,"absolute_offset":offsets[n],"submatches":subs}}
            else:
                item={"type":"context","data":{"path":{"text":path},"lines":{"text":text},"line_number":n+1,"absolute_offset":offsets[n],"submatches":[]}}
            output.append(item)
        output.append({"type":"end","data":{"path":{"text":path},"binary_offset":None,"stats":{"searches":1,"searches_with_match":1,"bytes_searched":off,"matched_lines":sum(1 for n,_,_ in hits),"matches":sum(len(ms) for _,_,ms in hits)}}})
    scans=scan_stats or {}
    output.append({"type":"summary","data":{"stats":{"searches":scans.get("searches",total_searches),"searches_with_match":total_searches,"bytes_searched":scans.get("bytes_searched",total_bytes),"matched_lines":total_lines,"matches":total_matches}}})
    return "".join(json.dumps(x,separators=(",",":"),ensure_ascii=False)+"\n" for x in output)
